-- Global session library seed (2026-10-25): 28 entries written by Claude for
-- owner review. Global = organization_id NULL, approved. Entries whose
-- evidence is HYROX practitioner consensus rather than trials are marked
-- status 'reference'. Idempotent: re-running updates content in place.

ON CONFLICT ON CONSTRAINT session_library_org_code_key DO UPDATE SET
  name = EXCLUDED.name, discipline = EXCLUDED.discipline, slot_type = EXCLUDED.slot_type,
  subtype = EXCLUDED.subtype, intensity = EXCLUDED.intensity, objective = EXCLUDED.objective,
  execution = EXCLUDED.execution, progression = EXCLUDED.progression,
  contraindications = EXCLUDED.contraindications, rationale = EXCLUDED.rationale,
  evidence_refs = EXCLUDED.evidence_refs, status = EXCLUDED.status;

UPDATE public.session_library SET is_approved = true, approved_at = COALESCE(approved_at, now())
WHERE organization_id IS NULL AND NOT is_approved;
