INSERT INTO public.session_library
  (code, name, discipline, slot_type, subtype, intensity, objective, execution, progression, contraindications, rationale, evidence_refs, status)
VALUES
  ('RUN_EASY', 'Easy aerobic run', 'run'::public.discipline, 'run', 'easy', 'easy', 'Build aerobic base and running durability at low physiological cost.', '30–70 min continuous at Easy pace (computed E zone) — conversational, RPE 3–4, HR below the athlete''s aerobic threshold. Flat or rolling terrain.', 'Add 5–10 min per week within the plan''s weekly run-km cap; never progress both duration and pace in the same week.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h.', 'Most weekly running volume should be easy so the hard sessions can be truly hard; easy volume drives mitochondrial and capillary adaptations with little fatigue.', ARRAY['Seiler 2010, Int J Sports Physiol Perform — intensity distribution in endurance athletes (~80/20)', 'Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces']::text[], 'validated'),
  ('RUN_RECOVERY', 'Recovery run', 'run'::public.discipline, 'run', 'easy', 'easy', 'Promote recovery between hard days while keeping running frequency.', '20–35 min very easy, slower than E pace (RPE 2–3). Stop early if legs feel worse after 10 min.', 'Does not progress — keep it short and easy; replace with rest or mobility when TSB is very negative.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Replace with rest when form (TSB) is in the high-risk band.', 'Very low intensity adds frequency and blood flow without adding meaningful training stress, protecting the next quality session.', ARRAY['Seiler 2010, Int J Sports Physiol Perform — intensity distribution in endurance athletes (~80/20)', 'Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces']::text[], 'validated'),
  ('RUN_LONG', 'Long run', 'run'::public.discipline, 'run', 'long', 'easy', 'Extend aerobic endurance and musculoskeletal tolerance for the 8 km of race running under fatigue.', '60–110 min at Easy pace (E zone), RPE 4. Fuel and hydrate as for a race on runs over 75 min.', 'Grow by ≤10 % per week and cap at ~25–30 % of weekly run volume; hold or cut back in recovery weeks.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not in the final 7 days before a race.', 'Time on feet at low intensity improves fatigue resistance and economy late in a session — exactly what HYROX runs 5–8 demand.', ARRAY['Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces', 'Gabbett 2016, Br J Sports Med — training–injury prevention paradox (load progression)']::text[], 'validated'),
  ('RUN_PROGRESSION', 'Progression run', 'run'::public.discipline, 'run', 'long', 'moderate', 'Practice running faster while fatigued and finishing strong.', '45–75 min: first two-thirds at Easy pace, final third building to Marathon then Threshold pace (M→T zones), finishing at RPE 7.', 'Lengthen the faster final segment by 5 min every 1–2 weeks.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Counts as a quality session — not on the day before or after another hard session.', 'A controlled finish at faster paces trains pacing discipline and fatigue resistance with less stress than a full tempo run.', ARRAY['Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces']::text[], 'validated'),
  ('RUN_STRIDES', 'Easy run + strides', 'run'::public.discipline, 'run', 'easy', 'easy', 'Keep leg speed and running economy without adding fatigue.', '30–45 min Easy, then 6–8 × 20 s strides at Repetition-pace feel (fast, relaxed, not sprinting) with 60–90 s walk/jog between.', 'Go from 6 to 10 strides; keep each stride ≤20 s.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Skip strides with any calf or Achilles soreness.', 'Short fast efforts improve neuromuscular coordination and economy with negligible metabolic cost.', ARRAY['Barnes & Kilding 2015, Sports Med — strategies to improve running economy', 'Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces']::text[], 'validated'),
  ('RUN_TEMPO', 'Tempo run', 'run'::public.discipline, 'run', 'tempo', 'hard', 'Raise lactate threshold — the pace you can sustain for HYROX''s running legs.', '15 min Easy warm-up, 20–30 min continuous at Threshold pace (T zone, comfortably hard, RPE 7), 10 min Easy cool-down.', 'Extend the tempo block by 5 min per week up to 35–40 min, or switch to cruise intervals.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not when form is in the fatigued/high-risk band; not within 48 h of another hard session.', 'Sustained threshold work is a time-efficient way to lift threshold pace and is directly specific to HYROX''s 8 × 1 km.', ARRAY['Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces', 'Seiler 2010, Int J Sports Physiol Perform — intensity distribution in endurance athletes (~80/20)']::text[], 'validated'),
  ('RUN_CRUISE_INTERVALS', 'Threshold cruise intervals', 'run'::public.discipline, 'run', 'tempo', 'hard', 'Accumulate more time at threshold than a continuous tempo allows.', '15 min Easy warm-up, 3–5 × 8 min at Threshold pace (T zone) with 1–2 min easy jog, 10 min cool-down.', 'Add one repetition every 1–2 weeks (max 5 × 8 min), then shorten recoveries to 60 s.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not within 48 h of another hard session.', 'Short recoveries keep lactate near threshold while splitting the work makes the total volume tolerable.', ARRAY['Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces']::text[], 'validated'),
  ('RUN_THRESHOLD_5X6', 'Threshold 5 × 6 min', 'run'::public.discipline, 'run', 'tempo', 'hard', 'Threshold development with HYROX-like work durations (each 1 km run takes ~4–6 min).', '15 min Easy warm-up, 5 × 6 min at Threshold pace (T zone) with 90 s easy jog, 10 min cool-down.', 'Move from 5 to 6 repetitions, then cut recoveries to 60 s.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not within 48 h of another hard session.', 'Matches the duration of a HYROX run segment while keeping the stimulus at threshold.', ARRAY['Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces', 'HYROX format (8 × 1 km run + 8 stations): practitioner consensus — no controlled trials of HYROX-specific sessions yet']::text[], 'validated'),
  ('RUN_VO2_4X4', 'VO2max 4 × 4 min', 'run'::public.discipline, 'run', 'interval', 'hard', 'Raise VO2max — the ceiling that threshold and race pace sit under.', '15 min Easy warm-up, 4 × 4 min at 90–95 % HRmax (Interval pace, I zone; RPE 8–9) with 3 min active recovery, 10 min cool-down.', 'Once 4 × 4 is controlled, increase pace slightly rather than adding reps; use at most once per week.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not in base phase for beginners; not when form is fatigued; never within 48 h of another hard session.', 'The 4 × 4 protocol is among the best-supported interval formats for improving VO2max in trained adults.', ARRAY['Helgerud et al. 2007, Med Sci Sports Exerc — 4×4 min aerobic intervals raise VO2max', 'Billat 2001, Sports Med — interval training for performance (parts I–II)']::text[], 'validated'),
  ('RUN_VO2_SHORT', 'Short VO2 intervals', 'run'::public.discipline, 'run', 'interval', 'hard', 'Accumulate time near VO2max with shorter, more repeatable efforts.', '15 min Easy warm-up, 2 sets of 8–10 × 400 m (or 90 s) at Interval pace (I zone) with 60–90 s jog, 3 min between sets, 10 min cool-down.', 'Add repetitions to the second set; keep paces consistent across reps rather than chasing speed.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not within 48 h of another hard session.', 'Short intervals with brief recoveries keep oxygen uptake high while reducing the per-rep strain of longer intervals.', ARRAY['Billat 2001, Sports Med — interval training for performance (parts I–II)', 'Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces']::text[], 'validated'),
  ('RUN_HILLS', 'Hill repeats', 'run'::public.discipline, 'run', 'interval', 'hard', 'Build running-specific strength and power with lower impact than flat speed work.', '15 min Easy warm-up, 8–10 × 60–90 s uphill (4–8 % grade) at hard effort (RPE 8), jog back down to recover, 10 min cool-down. Treadmill incline works.', 'Add 2 repetitions per week up to 12, or lengthen reps to 2 min.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Avoid with active Achilles or calf issues.', 'Uphill running loads the posterior chain and improves economy and power with reduced eccentric impact.', ARRAY['Barnes & Kilding 2015, Sports Med — strategies to improve running economy']::text[], 'validated'),
  ('RUN_FARTLEK', 'Fartlek', 'run'::public.discipline, 'run', 'fartlek', 'moderate', 'Unstructured speed variation that develops pace changes and aerobic power.', '40–55 min total: after 15 min Easy, alternate 1–3 min at Threshold-to-Interval feel with equal easy running for 20–25 min, then cool down.', 'Extend the fast portions toward 3 min and shorten the floats.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h.', 'Varying pace without strict targets builds the ability to surge and recover — useful for the run-after-station transitions.', ARRAY['Billat 2001, Sports Med — interval training for performance (parts I–II)']::text[], 'validated'),
  ('RUN_HYROX_1K_REPEATS', 'HYROX race-pace 1 km repeats', 'run'::public.discipline, 'run', 'interval', 'race_pace', 'Rehearse goal HYROX run-split pace until it feels automatic.', '15 min Easy warm-up, 5–8 × 1 km at goal HYROX run pace (from the athlete''s target run split) with 2 min recovery (walk/jog or a light station movement), 10 min cool-down.', 'Add repetitions toward 8, then shorten recoveries to 90 s in the peak phase.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not in the final 5 days before a race.', 'Race-specific pace practice improves pacing accuracy; the 1 km distance matches each HYROX run exactly.', ARRAY['HYROX format (8 × 1 km run + 8 stations): practitioner consensus — no controlled trials of HYROX-specific sessions yet', 'Daniels, Daniels'' Running Formula, 3rd ed. — E/M/T/I/R training paces']::text[], 'reference'),
  ('STR_LOWER_HEAVY', 'Lower-body heavy strength', 'strength'::public.discipline, 'strength', 'lower', 'hard', 'Increase maximal leg strength for sled push/pull, lunges and wall balls.', 'Warm-up 10 min. Back or front squat 4 × 4–6 @ RPE 7–8; Romanian deadlift 3 × 6–8; Bulgarian split squat 3 × 8/leg; calf raise 3 × 12. Rest 2–3 min on main lifts.', 'Add load when all reps are completed at the target RPE; deload every 4th week.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Keep ≥6 h (ideally a separate day) from hard running sessions.', 'Heavy strength work improves running economy and force production without meaningful hypertrophy when volume is kept moderate.', ARRAY['Rønnestad & Mujika 2014, Scand J Med Sci Sports — strength training improves endurance performance', 'Wilson et al. 2012, J Strength Cond Res — concurrent training interference meta-analysis']::text[], 'validated'),
  ('STR_UPPER_PUSH_PULL', 'Upper-body push/pull', 'strength'::public.discipline, 'strength', 'upper', 'moderate', 'Build pulling and pushing strength for sled pull, SkiErg, rowing and wall balls.', 'Pull-up or lat pulldown 4 × 6–8; push press 4 × 5; single-arm row 3 × 10/side; push-up 3 × max-2; face pull 3 × 15.', 'Add load or reps weekly in small steps; keep 1–2 reps in reserve.', 'Modify with shoulder pain (no overhead pressing).', 'Upper-body strength carries over to the pulling stations, which are often where mid-pack athletes lose the most time.', ARRAY['Rønnestad & Mujika 2014, Scand J Med Sci Sports — strength training improves endurance performance', 'Lauersen et al. 2014, Br J Sports Med — strength training reduces sports injuries']::text[], 'validated'),
  ('STR_FULL_BODY', 'Full-body strength', 'strength'::public.discipline, 'strength', 'full_body', 'moderate', 'Time-efficient strength maintenance across all major movement patterns.', 'Trap-bar deadlift 3 × 5; goblet squat 3 × 8; dumbbell bench or push-up 3 × 8–10; inverted row 3 × 10; farmer carry 4 × 40 m.', 'Progress load on the first two lifts; keep total session ≤60 min.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h.', 'With limited sessions per week, full-body work maintains strength in every pattern HYROX uses while minimising interference with running.', ARRAY['Rønnestad & Mujika 2014, Scand J Med Sci Sports — strength training improves endurance performance', 'Wilson et al. 2012, J Strength Cond Res — concurrent training interference meta-analysis']::text[], 'validated'),
  ('STR_POSTERIOR_UNILATERAL', 'Posterior chain & single-leg', 'strength'::public.discipline, 'strength', 'posterior', 'moderate', 'Strengthen hamstrings, glutes and single-leg stability — the usual weak links for running injuries.', 'Single-leg RDL 3 × 8/leg; hip thrust 4 × 8; Nordic or slider hamstring curl 3 × 6; step-up 3 × 8/leg; side plank 3 × 30 s/side.', 'Add load to hip thrust and step-ups; progress Nordic range before adding reps.', 'Reduce Nordic volume with hamstring soreness; skip or replace with easy cross-training if the athlete reported pain in the last 72 h.', 'Unilateral and posterior-chain strength work is associated with fewer running-related injuries and carries over to lunges.', ARRAY['Lauersen et al. 2014, Br J Sports Med — strength training reduces sports injuries']::text[], 'validated'),
  ('STR_POWER_LOW_VOLUME', 'Low-volume power (peak/taper)', 'strength'::public.discipline, 'strength', 'power', 'moderate', 'Keep strength and power through the peak and taper without accumulating fatigue.', 'Box jump 4 × 3; trap-bar jump or kettlebell swing 4 × 5; squat 3 × 3 @ RPE 6–7; med-ball throw 3 × 5. Full recovery between sets; under 40 min.', 'Does not progress — volume drops through the taper while intensity stays moderate.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. No jumping with knee or Achilles pain.', 'Maintaining intensity while cutting volume preserves strength during a taper; low-volume power work avoids residual fatigue on race day.', ARRAY['Bosquet et al. 2007, Med Sci Sports Exerc — tapering meta-analysis', 'Rønnestad & Mujika 2014, Scand J Med Sci Sports — strength training improves endurance performance']::text[], 'validated'),
  ('STR_CORE_ANTI_ROTATION', 'Core & anti-rotation', 'accessories'::public.discipline, 'strength', 'core', 'easy', 'Trunk stiffness for carries, sandbag lunges and wall balls.', 'Pallof press 3 × 10/side; dead bug 3 × 8/side; suitcase carry 4 × 30 m/side; plank variations 3 × 40 s. 20–30 min.', 'Add load to carries and Pallof press; lengthen holds.', 'Stop with lower-back pain beyond mild fatigue.', 'Anti-rotation and carry work trains the bracing used under load in the farmers carry and sandbag stations.', ARRAY['Lauersen et al. 2014, Br J Sports Med — strength training reduces sports injuries']::text[], 'validated'),
  ('MOB_FLOW', 'Mobility flow', 'mobility'::public.discipline, 'mobility_technique', 'mobility', 'easy', 'Maintain range of motion for hips, ankles and thoracic spine.', '20–30 min: hip airplanes, 90/90 switches, ankle dorsiflexion rocks, thoracic rotations, couch stretch (2 × 60 s/side), deep squat hold. Slow and controlled.', 'Add positions where the athlete is most restricted; increase hold time.', 'None beyond acute injury.', 'Regular mobility work maintains the positions needed for squats, lunges and wall balls; dynamic work before training doesn''t impair performance.', ARRAY['Behm et al. 2016, Appl Physiol Nutr Metab — acute effects of stretching and dynamic warm-up']::text[], 'validated'),
  ('TECH_RUN_DRILLS', 'Running drills', 'mobility'::public.discipline, 'mobility_technique', 'run_mechanics', 'easy', 'Improve running mechanics and coordination.', 'After 10 min easy jog: A-skips, B-skips, high knees, butt kicks, straight-leg bounds (2 × 20 m each), then 4 × 80 m relaxed strides.', 'Increase drill speed while keeping form; add single-leg hops if pain-free.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h.', 'Drills and strides reinforce efficient mechanics and are a low-fatigue way to work on running economy.', ARRAY['Barnes & Kilding 2015, Sports Med — strategies to improve running economy']::text[], 'validated'),
  ('TECH_STATION_SKILLS', 'Station technique', 'hyrox_station'::public.discipline, 'mobility_technique', 'skill_drill', 'easy', 'Make station movements efficient so they cost less energy on race day.', 'Pick 2–3 stations; 3–4 × 1–2 min of submaximal, technique-focused work each (SkiErg stroke timing, sled push body angle, burpee-broad-jump rhythm, wall-ball catch and squat depth). Video if possible.', 'Move from technique pace to race pace once the movement is consistent.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h.', 'Station time is largely technique-limited for most athletes; practising efficient movement at low fatigue transfers to race pace.', ARRAY['HYROX format (8 × 1 km run + 8 stations): practitioner consensus — no controlled trials of HYROX-specific sessions yet']::text[], 'reference'),
  ('PREHAB_LOWER_LEG', 'Lower-leg prehab', 'prehab'::public.discipline, 'mobility_technique', 'rehab', 'easy', 'Build calf, Achilles and foot capacity to tolerate running volume.', 'Straight-knee calf raise 3 × 15; bent-knee calf raise 3 × 15; tibialis raise 3 × 15; single-leg balance 3 × 30 s/side; foot doming 2 × 10. 15–20 min.', 'Add load to calf raises; progress to single-leg and slow eccentrics.', 'With an existing injury, follow the clinician''s protocol instead.', 'Lower-leg strength work is a low-cost way to reduce common running overuse injuries as volume rises.', ARRAY['Lauersen et al. 2014, Br J Sports Med — strength training reduces sports injuries', 'Gabbett 2016, Br J Sports Med — training–injury prevention paradox (load progression)']::text[], 'validated'),
  ('HYX_COMPROMISED_BRICK', 'Compromised running brick', 'hyrox_station'::public.discipline, 'hyrox', 'brick', 'hard', 'Learn to run at target pace straight after a station.', 'Warm-up 15 min. 4–6 rounds: 1 station block at race effort (e.g. 500 m SkiErg, 25 m sled push, 20 wall balls) → immediately 1 km at goal HYROX run pace. 2–3 min between rounds.', 'Add rounds, then rotate the hardest stations (sleds, lunges) before the runs.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Counts as a hard session; not within 48 h of another.', 'Running immediately after a station is the defining demand of HYROX; rehearsing the transition improves pacing on legs 2–8.', ARRAY['HYROX format (8 × 1 km run + 8 stations): practitioner consensus — no controlled trials of HYROX-specific sessions yet']::text[], 'reference'),
  ('HYX_STATION_ENDURANCE', 'Station endurance circuit', 'hyrox_station'::public.discipline, 'hyrox', 'station_endurance', 'moderate', 'Raise the volume of station work the athlete can sustain without breaking.', '3–4 rounds at steady effort: 250 m row, 15 wall balls, 20 m sandbag lunge, 40 m farmers carry, 10 burpee broad jumps. 2 min between rounds.', 'Add a round or increase loads toward race weights.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h.', 'Muscular endurance at race loads limits station time for most athletes; steady circuits build it without maximal fatigue.', ARRAY['HYROX format (8 × 1 km run + 8 stations): practitioner consensus — no controlled trials of HYROX-specific sessions yet']::text[], 'reference'),
  ('HYX_ERG_INTERVALS', 'SkiErg / Row intervals', 'hyrox_station'::public.discipline, 'hyrox', 'erg', 'hard', 'Build pacing and aerobic power on the two erg stations.', '10 min easy erg warm-up; 6–8 × 250 m alternating SkiErg and row at goal race pace per 500 m, 1 min rest; then 2 × 1000 m steady.', 'Lengthen reps to 500 m; tighten pace consistency between reps.', 'Modify with shoulder or lower-back pain.', 'Erg pacing is learnable and low-impact, letting athletes add aerobic work without extra running load.', ARRAY['Billat 2001, Sports Med — interval training for performance (parts I–II)', 'HYROX format (8 × 1 km run + 8 stations): practitioner consensus — no controlled trials of HYROX-specific sessions yet']::text[], 'reference'),
  ('HYX_HALF_SIM', 'Half simulation', 'hyrox_station'::public.discipline, 'hyrox', 'simulation', 'race_pace', 'Test pacing and fuelling over half a race.', 'Warm-up 15 min. 4 × (1 km at goal run pace + one station at race weight), in race order (either stations 1–4 or 5–8). Record splits.', 'Alternate halves across blocks; compare splits with the previous attempt.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not in the final 7 days before a race; not when form is fatigued.', 'A half simulation provides race-specific feedback at a fraction of the recovery cost of a full simulation.', ARRAY['HYROX format (8 × 1 km run + 8 stations): practitioner consensus — no controlled trials of HYROX-specific sessions yet', 'Gabbett 2016, Br J Sports Med — training–injury prevention paradox (load progression)']::text[], 'reference'),
  ('HYX_FULL_SIM', 'Full simulation', 'hyrox_station'::public.discipline, 'hyrox', 'simulation', 'race_pace', 'Full race rehearsal: pacing, transitions, fuelling and equipment.', 'Full course at goal pace: 8 × (1 km + station) in race order, with Roxzone transitions timed. Treat as a race-day dress rehearsal.', 'At most once every 3–4 weeks, in the build/peak phases only.', 'Skip or replace with easy cross-training if the athlete reported pain in the last 72 h. Not in base phase; not in the final 10 days before a race; not when form is fatigued or high-risk.', 'Occasional full rehearsals expose pacing and fuelling errors, but their fatigue cost means they should be rare and placed well before the taper.', ARRAY['HYROX format (8 × 1 km run + 8 stations): practitioner consensus — no controlled trials of HYROX-specific sessions yet', 'Bosquet et al. 2007, Med Sci Sports Exerc — tapering meta-analysis']::text[], 'reference')
